1: {% extends "user_sessions/_base.html" %}
2: {% load user_sessions i18n future %}
3: 
4: {% block content %}
5:   <h1>{% trans "Active Sessions" %}</h1>
6: 
7:   <table class="table">
8:     <thead>
9:       <tr>
10:         <th>{% trans "Location" %}</th>
11:         <th>{% trans "Device" %}</th>
12:         <th>{% trans "Last Activity" %}</th>
13:         <th>{% trans "End Session" %}</th>
14:       </tr>
15:     </thead>
16:     {% for object in object_list %}
17:       <tr {% if object.session_key == session_key %}class="active"{% endif %}>
18:         <td>{{ object.ip|location }} <small>({{ object.ip }})</small></td>
19:         <td>{{ object.user_agent|device }}</td>
20:         <td>
21:           {% if object.session_key == session_key %}
22:             {% blocktrans with time=object.last_activity|timesince %}{{ time }} ago (this session){% endblocktrans %}
23:           {% else %}
24:             {% blocktrans with time=object.last_activity|timesince %}{{ time }} ago{% endblocktrans %}
25:           {% endif %}
26:         </td>
27:         <td>
28:           <form method="post" action="{% url 'user_sessions:session_delete' object.pk %}">
29:             {% csrf_token %}
30:             {% if object.session_key == session_key %}
31:               <button type="submit" class="btn btn-xs btn-link">{% trans "End Session" %}</button>
32:             {% else %}
33:               <button type="submit" class="btn btn-xs btn-warning">{% trans "End Session" %}</button>
34:             {% endif %}
35:           </form>
36:         </td>
37:       </tr>
38:     {% endfor %}
39:   </table>
40: 
41:   {% if object_list.count > 1 %}
42:     <form method="post" action="{% url 'user_sessions:session_delete_other' %}">
43:       {% csrf_token %}
44:       <p>{% blocktrans %}You can also end all other sessions but the current.
45:         This will log you out on all other devices.{% endblocktrans %}</p>
46:       <button type="submit" class="btn btn-default btn-warning">{% trans "End All Other Sessions" %}</button>
47:     </form>
48:   {% endif %}
49: {% endblock %}

